<script setup lang="ts">
import { computed, ref } from 'vue';
import { normalizeComfyWorkflow } from '../workflow-import';
import { resolveWorkbenchImageBindings } from '@qwendirector/workflow-adapters/workbench-image-bindings';
const props = defineProps<{ apiToken?: string }>();
type WorkflowKind = 'h3'|'actor'|'scene'|'prop'|'layout'|'image-edit'|'image-generate'|'refmod-create';
const emit = defineEmits<{ save: [payload: { name: string; graph: Record<string, unknown>; kind?: Exclude<WorkflowKind,'h3'>; imageNodeIds: string[]; audioNodeIds: string[]; videoNodeIds: string[]; outputBindings: Record<string,string> }] }>();
const open = ref(false); const step = ref(1); const name = ref('H3 workflow'); const json = ref(''); const imageIds = ref(''); const audioIds = ref(''); const videoIds = ref(''); const error = ref(''); const kind = ref<WorkflowKind>('h3'); const outputBindings = ref<Record<string,string>>({});
const graph = computed(() => { try { const value = JSON.parse(json.value); return value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : null; } catch { return null; } });
const semanticImageNodeIds = computed(() => {
  if (kind.value !== 'image-edit' || !graph.value) return [];
  try { return resolveWorkbenchImageBindings('image-edit', graph.value as Record<string, any>); }
  catch { return []; }
});
const imageSlotOrderLabel = computed(() => semanticImageNodeIds.value.map((id, index) => `image_${index + 1} → ${id}`).join(' · '));
const outputSlots: Record<string, string[]> = { actor: ['master','turnaround'], scene: ['establishing','angles'], prop: ['master','detail'], layout: ['layout'] };
const boundary = computed(() => {
  if (!graph.value) return null;
  const entries = Object.entries(graph.value); const classes = (name: string) => entries.filter(([, node]) => (node as any)?.class_type === name).map(([id]) => id);
  const h3 = classes('MiniMaxH3ReferenceToVideo'); const i2va = classes('MiniMaxH3ImageToVideo'); const noise = classes('RandomNoise'); const save = classes('SaveVideo'); const advancedSave = classes('SaveImageAdvanced'); const encoder = classes('TextEncodeQwenImage21'); const videos = classes('VHS_VideoCombine'); const upscaler = classes('MMH3UltimateUpscale'); const veda = classes('VedaSparseAttention'); const images = classes('LoadImage'); const emptyLatent = classes('EmptyLatentImage'); const sampler = classes('KSampler'); const audios = classes('LoadAudio'); const creators = classes('H3RefModCreateFromFolder'); const vaes = classes('VAELoader'); const videoInputs = [...classes('VHS_LoadVideo'), ...classes('VHS_LoadVideoPath'), ...classes('LoadVideo')];
  const imageBindings = kind.value === 'image-edit' ? semanticImageNodeIds.value : imageIds.value.split(',').map((v) => v.trim()).filter(Boolean); const audioBindings = audioIds.value.split(',').map((v) => v.trim()).filter(Boolean); const videoBindings = videoIds.value.split(',').map((v) => v.trim()).filter(Boolean); const inputsValid = imageBindings.length === images.length && new Set(imageBindings).size === imageBindings.length && imageBindings.every((id) => images.includes(id)) && audioBindings.every((id) => audios.includes(id)) && new Set(audioBindings).size === audioBindings.length && videoBindings.every((id) => videoInputs.includes(id)) && new Set(videoBindings).size === videoBindings.length;
  const imageSavers = [...classes('SaveImage'), ...advancedSave]; const slots = outputSlots[kind.value] ?? []; const mappedSlots = imageSavers.map((id) => outputBindings.value[id]); const outputBindingsValid = imageSavers.length > 0 && imageSavers.length === Object.keys(outputBindings.value).length && mappedSlots.every((slot) => slots.includes(slot)) && new Set(mappedSlots).size === mappedSlots.length;
  const isWorkbench = Object.hasOwn(outputSlots, kind.value); const isVeda = upscaler.length === 1 && veda.length > 0; const h3ImageNode = i2va.length === 1 ? (graph.value as any)[i2va[0]] : undefined; const firstFrameId = h3ImageNode?.inputs?.first_frame?.[0]; const lastFrameId = h3ImageNode?.inputs?.last_frame?.[0]; const isFl2va = i2va.length === 1 && Boolean(lastFrameId); const isI2va = i2va.length === 1 && !lastFrameId; const imageEdit = encoder.length > 0 && advancedSave.length > 0 && images.length > 0; const imageGenerate = encoder.length === 1 && advancedSave.length === 1 && images.length === 0 && emptyLatent.length > 0 && sampler.length > 0;
  const refmod = creators.length === 1 && vaes.length > 0 && (graph.value as any)[creators[0]]?.inputs?.save === true && (graph.value as any)[creators[0]]?.inputs?.save_layout === 'bundle' && (graph.value as any)[creators[0]]?.inputs?.use_subfolders !== true && Array.isArray((graph.value as any)[creators[0]]?.inputs?.vae) && (graph.value as any)[creators[0]].inputs.vae[0] === vaes[0];
  const fl2vaFrameIds = [firstFrameId, lastFrameId]; const fl2vaBindingsValid = isFl2va && h3.length === 0 && noise.length === 1 && save.length === 1 && images.length === 2 && imageBindings.length === 2 && inputsValid && fl2vaFrameIds.every((id, index) => id === imageBindings[index]) && new Set(fl2vaFrameIds).size === 2;
  const i2vaBindingValid = isI2va && h3.length === 0 && noise.length === 1 && save.length === 1 && images.length === 1 && imageBindings.length === 1 && inputsValid && firstFrameId === imageBindings[0];
  const valid = isWorkbench ? images.length > 0 && inputsValid && outputBindingsValid : kind.value === 'refmod-create' ? refmod : imageEdit ? encoder.length === 1 && advancedSave.length === 1 && inputsValid : imageGenerate ? inputsValid : i2va.length === 1 ? (isFl2va ? fl2vaBindingsValid : i2vaBindingValid) : h3.length === 1 && (isVeda ? noise.length === 2 && videos.length === 2 : noise.length === 1 && save.length === 1) && inputsValid;
  return { h3, i2va, noise, save, advancedSave, encoder, videos, isVeda, isFl2va, isI2va, imageEdit, imageGenerate, refmod, images, audios, imageSavers, outputBindingsValid, valid };
});
function setKind(value: WorkflowKind) { kind.value = value; outputBindings.value = {}; const ids = boundary.value?.imageSavers ?? []; const slots = outputSlots[value] ?? []; if (ids.length === 1 && slots.length > 0) outputBindings.value[ids[0]] = slots[0]; }
async function importFile(event: Event) {
  const input = event.target as HTMLInputElement; const file = input.files?.[0]; if (!file) return;
  try {
    const headers: Record<string,string> = { 'content-type': 'application/json' }; if (props.apiToken) headers.authorization = `Bearer ${props.apiToken}`;
    const imported = await normalizeComfyWorkflow(JSON.parse(await file.text()), (url, init) => window.fetch(url, { ...init, headers: { ...headers, ...(init?.headers as Record<string,string> | undefined) } }));
    json.value = JSON.stringify(imported, null, 2); const classes = Object.values(imported).map((node: any) => node?.class_type); const importedI2va = Object.values(imported).find((node: any) => node?.class_type === 'MiniMaxH3ImageToVideo') as any;
    if (importedI2va) imageIds.value = [importedI2va.inputs?.first_frame?.[0], importedI2va.inputs?.last_frame?.[0]].filter(Boolean).join(',');
    const isGenericImageGraph = classes.includes('LoadImage') && (classes.includes('SaveImage') || classes.includes('SaveImageAdvanced')) && !classes.includes('MiniMaxH3ReferenceToVideo') && !classes.includes('MiniMaxH3ImageToVideo') && !classes.includes('TextEncodeQwenImage21');
    const nextKind: WorkflowKind = classes.includes('H3RefModCreateFromFolder') ? 'refmod-create' : classes.includes('TextEncodeQwenImage21') && classes.includes('SaveImageAdvanced') ? (classes.includes('LoadImage') ? 'image-edit' : classes.includes('EmptyLatentImage') && classes.includes('KSampler') ? 'image-generate' : 'h3') : isGenericImageGraph ? 'actor' : 'h3';
    kind.value = nextKind; outputBindings.value = {};
    if (classes.includes('MiniMaxH3ImageToVideo')) name.value = importedI2va?.inputs?.last_frame?.[0] ? 'MiniMax H3 FL2VA' : 'MiniMax H3 I2VA';
    if (nextKind === 'image-edit' || nextKind === 'actor') { name.value = nextKind === 'actor' ? 'ComfyUI actor workbench' : 'Qwen Image 2.1 image edit'; imageIds.value = Object.entries(imported).filter(([, node]: [string, any]) => node?.class_type === 'LoadImage').map(([id]) => id).join(','); }
    else if (nextKind === 'image-generate') { name.value = 'Qwen Image 2.1 text to image'; imageIds.value = ''; audioIds.value = ''; videoIds.value = ''; }
    else if (nextKind === 'refmod-create') { name.value = 'MiniMax H3 RefMod'; imageIds.value = ''; audioIds.value = ''; videoIds.value = ''; }
    step.value = 2; error.value = '';
    if (Object.hasOwn(outputSlots, nextKind)) { const ids = boundary.value?.imageSavers ?? []; const slots = outputSlots[nextKind] ?? []; if (ids.length === 1 && slots.length > 0) outputBindings.value[ids[0]] = slots[0]; }
  } catch (cause) { error.value = (cause as Error).message; } finally { input.value = ''; }
}
function next() { error.value = ''; if (step.value === 1 && !graph.value) { error.value = 'Загрузите workflow JSON из ComfyUI (UI или API format)'; return; } const missingBindings = kind.value === 'image-edit' && !imageIds.value.trim() || kind.value === 'h3' && !boundary.value?.isVeda && !imageIds.value.trim(); if (step.value === 2 && (missingBindings || !boundary.value?.valid)) { error.value = 'Проверьте image bindings, output saver → slot и workflow boundary'; return; } step.value = Math.min(4, step.value + 1); }
function save() { if (!graph.value || !boundary.value?.valid) { error.value = 'Boundary не прошёл проверку'; return; } emit('save', { name: name.value.trim() || 'H3 workflow', graph: graph.value, ...(kind.value !== 'h3' ? { kind: kind.value } : {}), imageNodeIds: kind.value === 'image-edit' ? semanticImageNodeIds.value : imageIds.value.split(',').map((v) => v.trim()).filter(Boolean), audioNodeIds: audioIds.value.split(',').map((v) => v.trim()).filter(Boolean), videoNodeIds: videoIds.value.split(',').map((v) => v.trim()).filter(Boolean), outputBindings: outputBindings.value }); step.value = 4; }
</script>
<template><section class="workflow-wizard"><button type="button" class="uk-button uk-button-default" @click="open = !open">{{ open ? 'Свернуть мастер' : 'Импортировать workflow' }}</button><div v-if="open" class="wizard-panel"><div class="wizard-steps"><span v-for="n in 4" :key="n" :class="{active: step >= n }">{{ n }}</span></div><h3>Настройка {{ boundary?.isFl2va ? 'MiniMax H3 FL2VA' : boundary?.isI2va ? 'MiniMax H3 I2VA' : kind === 'h3' ? 'H3' : kind === 'refmod-create' ? 'MiniMax H3 RefMod' : Object.hasOwn(outputSlots, kind) ? `${kind} workbench` : 'Qwen Image 2.1' }} workflow</h3><label>Название профиля<input v-model="name" class="uk-input"></label><label v-if="step === 1">Workflow JSON из ComfyUI (UI или API format)<input type="file" accept="application/json,.json" class="uk-input" @change="importFile"><textarea v-model="json" class="uk-textarea" rows="4" placeholder="Или вставьте API-format JSON графа"></textarea></label><div v-else-if="step === 2"><label v-if="['actor','scene','prop','layout'].includes(kind)">Тип workbench<select :value="kind" class="uk-select" @change="setKind(($event.target as HTMLSelectElement).value as WorkflowKind)"><option value="actor">Actor</option><option value="scene">Scene</option><option value="prop">Prop</option><option value="layout">Layout</option></select></label><label v-if="kind !== 'image-generate' && kind !== 'refmod-create' && kind !== 'image-edit'">Image node IDs<input v-model="imageIds" class="uk-input" placeholder="Автоматически определяются при импорте"></label><p v-if="kind === 'image-edit'" class="uk-text-small">Qwen image order is fixed by the encoder slots: {{ imageSlotOrderLabel || 'не удалось связать image_N slots с LoadImage' }}.</p><label v-if="kind === 'h3'">Audio node IDs<input v-model="audioIds" class="uk-input" placeholder="10,11"></label><label v-if="kind === 'h3'">Video node IDs<input v-model="videoIds" class="uk-input" placeholder="12,13"></label><div v-if="boundary && Object.hasOwn(outputSlots, kind)"><label v-for="nodeId in boundary.imageSavers" :key="nodeId">Saver node {{ nodeId }} → слот<select v-model="outputBindings[nodeId]" class="uk-select"><option value="">Выбрать слот</option><option v-for="slot in outputSlots[kind]" :key="slot" :value="slot">{{ slot }}</option></select></label><p class="uk-text-small">Каждый saver должен иметь уникальный слот. Если граф выдаёт несколько файлов из одного saver, все они останутся в назначенном слоте.</p></div><p class="uk-text-small">{{ kind === 'refmod-create' ? `H3 RefMod · creator ${boundary?.refmod ? 'валиден' : 'нужны VAELoader и сохранение bundle'} · входные изображения будут упакованы в sidecar` : kind === 'image-edit' ? `Qwen edit · encoder ${boundary?.encoder.join(', ') || '—'} · image inputs ${boundary?.images.length ?? 0} · saver ${boundary?.advancedSave.join(', ') || '—'}` : kind === 'image-generate' ? `Qwen text-to-image · encoder ${boundary?.encoder.join(', ') || '—'} · empty latent ${boundary?.valid ? 'present' : 'missing'} · saver ${boundary?.advancedSave.join(', ') || '—'}` : Object.hasOwn(outputSlots, kind) ? `${kind} workbench · output saver ${boundary?.imageSavers.join(', ') || '—'} · slots ${boundary?.outputBindingsValid ? 'назначены' : 'требуется явное назначение'}` : `Boundary: H3 ${boundary?.isFl2va ? boundary?.i2va.join(', ') : boundary?.h3.join(', ') || '—'} · Noise ${boundary?.noise.join(', ') || '—'} · ${boundary?.isVeda ? `Video ${boundary?.videos.join(', ')}` : `Save ${boundary?.save.join(', ') || '—'}`}` }}</p></div><p v-else-if="step === 3" class="uk-text-small">Boundary {{ boundary?.valid ? 'подтверждён' : 'не прошёл проверку' }}. Сохраните candidate; live schema validation выполняется отдельно.</p><p v-else class="uk-text-success">Candidate сохранён. Теперь его можно выбрать для новых jobs.</p><p v-if="error" class="uk-text-danger">{{ error }}</p><div class="wizard-actions"><button v-if="step < 3" type="button" class="uk-button uk-button-default" @click="next">Далее</button><button v-if="step === 2" type="button" class="uk-button uk-button-default" @click="next">Проверить</button><button v-if="step === 3" type="button" class="uk-button uk-button-primary" @click="save">Сохранить кандидат</button></div></div></section></template>
<style scoped>
.workflow-wizard{margin:0 0 14px}.wizard-panel{margin-top:10px;padding:14px;border:1px solid var(--line,#303742);border-radius:10px;background:var(--surface-raised,#20252d)}.wizard-panel label{display:block;margin:8px 0}.wizard-panel textarea{margin-top:6px}.wizard-steps{display:flex;gap:8px;margin-bottom:10px}.wizard-steps span{width:24px;height:24px;border-radius:50%;display:grid;place-items:center;background:#303742;color:#97a1af;font-size:12px}.wizard-steps span.active{background:#367ed7;color:#fff}.wizard-actions{display:flex;gap:8px;margin-top:12px}
</style>
